from tools.chapter08_foundation_review.test_jt82_v3 import ROOT,load,proof
def test_current_stage_D12_dynamicResistance200_expiry558_preserves_native_parameters_CPP211_head():
 p=load();s=p['scenarioDraft'];s.pop('timeline');s.pop('branches',None);s['objectives']={};s['roster']=[];s['initialEntities']=[{'definition':'unit/peer/dynamic/source','instanceAlias':'source','position':{'row':0,'col':0}},{'definition':'unit/peer/dynamic/target','instanceAlias':'target','position':{'row':0,'col':1}}]
 for ident in ['source','target']:p['definitions'].append({'id':'unit/peer/dynamic/'+ident,'kind':'entity','components':{'attributes':{'base':{'max_hp':18000,'atk':77,'def':257,'mres':63,'one_minus_status_resistance':1}},'resources':{'hp':{'initial':18000,'capacity':18000,'role':'health'}},'spatial':{},'lifecycle':{'policy':'policy/ark_lifecycle'},'abilities':['ability/peer/dynamic/apply'] if ident=='source' else ['ability/peer/dynamic/resist']}})
 p['definitions'].append({'id':'buff/peer/dynamic/resist','kind':'buff','modifiers':[{'attribute':'one_minus_status_resistance','layer':'final_ratio','value':-.5}]});p['definitions'] += [{'id':'ability/peer/dynamic/apply','kind':'ability','activation':{'mode':'manual','on_start':[{'op':'buff_application','target':3,'application_rule':'rule/ch8/dragon_fire/application','allowed':['buff/ch8/source/dragon_fire','buff/ch8/source/dragon_fire[damage]']}]},'timeline':[]},{'id':'ability/peer/dynamic/resist','kind':'ability','activation':{'mode':'manual','on_start':[{'op':'apply_buff','target':'source','buff':'buff/peer/dynamic/resist'}]},'timeline':[]}]
 from ark_sim import Compiler,Engine
 from ark_sim.tools.replay import replay
