 reg=providers();pr=Compiler(providers=reg).compile(p);sim=Engine.create(pr,providers=reg,seed=s['seed']);sim.submit({'action':'skill','source':'source','ability':'ability/peer/dynamic/apply'},at=0);sim.submit({'action':'skill','source':'target','ability':'ability/peer/dynamic/resist'},at=200);sim.advance(211);d=OUT/'current_dynamic_D12';d.mkdir(parents=True,exist_ok=True);f=d/'checkpoint.json';h=write_ordered(f,sim.checkpoint());r=Engine.restore(pr,load_bound(f,h),providers=reg);sim.advance(360);r.advance(360);assert sim.checkpoint()==r.checkpoint()==replay(pr,sim.export_replay(),providers=reg).checkpoint();target=sim.session.world.resolve('target');hits=[e for e in sim.session.events if e['type']=='damage.accepted' and e['payload']['target']==target];assert [(e['time'],e['payload']['amount']) for e in hits]==[(t,50+180*t/900) for t in range(30,541,30)];removed=[e for e in sim.session.events if e['type']=='buff.removed' and e['payload']['buff']=='buff/ch8/source/dragon_fire'];assert [e['time'] for e in removed]==[558];assert 'buff/ch8/source/dragon_fire[damage]' in [i['definition'] for i in sim.ctx.get('target',('buffs','instances'))];(d/'evidence.json').write_text(json.dumps({'input':p,'cp_sha':h,'checkpoint':sim.checkpoint()},indent=2),encoding='utf8')
